/** The ESM build of @xterm/headless, imported by path: the package's `module` field names a file it
 *  does not ship (lib/xterm.mjs), so a bundler that prefers `module` cannot resolve the bare name.
 *  Same API as the package's own typings. */
declare module '@xterm/headless/lib-headless/xterm-headless.mjs' {
  export * from '@xterm/headless';
}
